const raw = $input.first().json;
const body = raw.body ?? raw;

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const source = body.source || body.workflow?.name || 'unknown';
const step = body.step || body.node?.name || body.context?.step || 'unknown';
const errorRaw =
  body.error?.message ||
  body.execution?.error?.message ||
  (typeof body.error === 'string' ? body.error : JSON.stringify(body.error || 'unknown error'));
const summary = body.summary || `Pipeline failure: ${step}`;
const incident_key =
  body.incident_key ||
  `${step}:${String(errorRaw).slice(0, 80).replace(/\s+/g, '-').toLowerCase()}`;

return [
  {
    json: {
      incident_id: body.incident_id || uuidv4(),
      incident_key,
      severity: body.severity || 'high',
      tier: body.tier ?? null,
      source,
      step,
      timestamp: body.timestamp || new Date().toISOString(),
      summary,
      error: errorRaw,
      context: {
        ...(body.context || {}),
        workflow_id: body.workflow?.id || body.context?.workflow_id,
        workflow_name: body.workflow?.name || body.context?.workflow_name,
        execution_id: body.execution?.id || body.context?.execution_id,
        execution_url: body.execution?.url || body.context?.execution_url,
        node_name: body.node?.name || body.context?.node_name,
        pipeline_run_id: body.pipeline_run_id || body.context?.pipeline_run_id,
        run_id: body.run_id || body.context?.run_id,
        counts: body.counts || body.context?.counts,
      },
      auto_fix_allowed: body.auto_fix_allowed !== false,
      constitution_reminder: 'Scoring logic Python-only; no score changes in prompts',
    },
  },
];

const staticData = $getWorkflowStaticData('global');
const item = $input.first().json;
const key = item.incident_key;
const now = Date.now();
const WINDOW_MS = 6 * 60 * 60 * 1000;

if (!staticData.recentIncidents) staticData.recentIncidents = {};

for (const [k, ts] of Object.entries(staticData.recentIncidents)) {
  if (now - ts > WINDOW_MS) delete staticData.recentIncidents[k];
}

if (staticData.recentIncidents[key]) {
  return [{ json: { ...item, _skip: true, _skip_reason: 'duplicate within 6h' } }];
}

staticData.recentIncidents[key] = now;
return [{ json: { ...item, _skip: false } }];

const item = $input.first().json;
if (item.tier !== null && item.tier !== undefined) {
  return [{ json: item }];
}

const error = String(item.error || '').toLowerCase();
const step = String(item.step || '').toLowerCase();
const summary = String(item.summary || '').toLowerCase();
const source = String(item.source || '').toLowerCase();
const workflowName = String(item.context?.workflow_name || '').toLowerCase();
const contextNode = String(item.context?.node_name || '').toLowerCase();
const incidentKey = String(item.incident_key || '').toLowerCase();
const combined = `${error} ${step} ${summary}`;

let tier = 2;
let auto_fix_allowed = true;

const normalizedError = error.replace(/^"+|"+$/g, '').trim();
const isGlobalErrorHandler =
  source.includes('global error handler') ||
  workflowName.includes('global error handler') ||
  incidentKey.includes('global-error-handler');
const isUnknownNode =
  step === 'unknown-node' ||
  step === 'unknown' ||
  contextNode === 'unknown-node' ||
  contextNode === 'unknown';
const isPlaceholderError =
  normalizedError === 'unknown error' || normalizedError === 'unknown-error';

if (isGlobalErrorHandler && isUnknownNode && isPlaceholderError) {
  return [{ json: { ...item, tier: 3, auto_fix_allowed: false } }];
}

const tier3Patterns = [
  'database_connected',
  'anthropic_api_key',
  'connection refused',
  'manual pipeline runs are disabled',
  '403 forbidden',
  'econnrefused',
  'enotfound',
  'ssl certificate',
  'railway',
  'timeout of 600',
  'dataset truncated',
  'row count drop',
];

if (tier3Patterns.some((p) => combined.includes(p))) {
  tier = 3;
  auto_fix_allowed = false;
}

const tier1Patterns = [
  'arcgis',
  'invalid query',
  'keyerror',
  'attributeerror',
  'importerror',
  'syntaxerror',
  'typeerror',
  'nameerror',
  '502',
  '400',
  '404 not found',
  'scrape',
  'field',
  'traceback',
];

if (tier === 2 && tier1Patterns.some((p) => combined.includes(p))) {
  tier = 1;
}

return [{ json: { ...item, tier, auto_fix_allowed } }];

